import{_ as n,o as t,c as e,a2 as r}from"./chunks/framework.DBU8LMUS.js";const u=JSON.parse('{"title":"Melaporkan Konten","description":"","frontmatter":{"title":"Melaporkan Konten","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/moderasi.md","filePath":"latest/moderasi.md","lastUpdated":1786334463000}'),o={name:"latest/moderasi.md"};function l(i,a,d,s,p,k){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="melaporkan-konten" tabindex="-1">Melaporkan Konten <a class="header-anchor" href="#melaporkan-konten" aria-label="Permalink to &quot;Melaporkan Konten&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Setiap pengguna dapat <strong>melaporkan konten</strong> yang dianggap melanggar aturan komunitas. Laporan diteruskan ke admin untuk ditinjau dan ditindaklanjuti. Modul ini menjelaskan jenis konten yang dapat dilaporkan dan cara melaporkannya.</p><h2 id="konten-yang-dapat-dilaporkan" tabindex="-1">Konten yang Dapat Dilaporkan <a class="header-anchor" href="#konten-yang-dapat-dilaporkan" aria-label="Permalink to &quot;Konten yang Dapat Dilaporkan&quot;">​</a></h2><p>Berikut jenis konten yang memiliki tombol <strong>Laporkan</strong>:</p><table tabindex="0"><thead><tr><th>Jenis Konten</th><th>Contoh Pelanggaran</th></tr></thead><tbody><tr><td><strong>Lowongan</strong></td><td>Lowongan palsu atau menyesatkan.</td></tr><tr><td><strong>Pengumuman</strong></td><td>Informasi tidak pantas atau tidak relevan.</td></tr><tr><td><strong>Polling</strong></td><td>Pertanyaan yang provokatif atau menyinggung.</td></tr><tr><td><strong>Grup</strong></td><td>Grup dengan konten atau tujuan melanggar aturan.</td></tr><tr><td><strong>Galeri</strong></td><td>Foto yang tidak pantas atau melanggar privasi.</td></tr><tr><td><strong>Profil</strong></td><td>Profil dengan informasi palsu atau menyesatkan.</td></tr></tbody></table><h2 id="melaporkan-konten-1" tabindex="-1">Melaporkan Konten <a class="header-anchor" href="#melaporkan-konten-1" aria-label="Permalink to &quot;Melaporkan Konten&quot;">​</a></h2><h3 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h3><ol><li>Buka halaman konten yang ingin dilaporkan (misalnya detail lowongan atau profil).</li><li>Klik tombol <strong>Laporkan</strong> pada konten tersebut.</li><li>Pilih atau tuliskan <strong>alasan pelaporan</strong>.</li><li>Klik <strong>Kirim Laporan</strong>.</li></ol><h3 id="setelah-melaporkan" tabindex="-1">Setelah Melaporkan <a class="header-anchor" href="#setelah-melaporkan" aria-label="Permalink to &quot;Setelah Melaporkan&quot;">​</a></h3><ul><li>Laporan diteruskan ke admin untuk ditinjau.</li><li>Status laporan dapat dipantau oleh admin pada panel <strong>Moderasi Konten</strong>.</li><li>Pengguna yang melaporkan tidak dapat melihat identitas satu sama lain secara publik.</li></ul><h2 id="batasan-pelaporan" tabindex="-1">Batasan Pelaporan <a class="header-anchor" href="#batasan-pelaporan" aria-label="Permalink to &quot;Batasan Pelaporan&quot;">​</a></h2><ul><li>Berikan laporan <strong>berdasarkan fakta</strong> dan alasan yang jelas.</li><li>Jangan menyalahgunakan fitur laporan (misalnya melaporkan konten yang sebenarnya tidak melanggar).</li><li>Penyalahgunaan berulang dapat dikenakan sanksi oleh admin.</li></ul><h2 id="apa-yang-terjadi-setelah-laporan" tabindex="-1">Apa yang Terjadi Setelah Laporan? <a class="header-anchor" href="#apa-yang-terjadi-setelah-laporan" aria-label="Permalink to &quot;Apa yang Terjadi Setelah Laporan?&quot;">​</a></h2><ol><li>Admin menerima laporan pada panel moderasi.</li><li>Admin meninjau konten yang dilaporkan.</li><li>Admin dapat <strong>menyelesaikan</strong> laporan (konten dianggap aman) atau <strong>menindaklanjuti</strong> (misalnya menghapus konten atau menonaktifkan pengguna).</li></ol><p>Lanjutkan ke <a href="/webapps/latest/admin/">Panduan Admin</a> untuk memahami tugas pengelola.</p>',16)])])}const h=n(o,[["render",l]]);export{u as __pageData,h as default};
